-- ----------------------------
-- Table structure for article
-- ----------------------------
DROP TABLE IF EXISTS `article`;
CREATE TABLE `article` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标题',
  `time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '时间',
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '内容',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='宠物百科管理';

-- ----------------------------
-- Records of article
-- ----------------------------
BEGIN;
INSERT INTO `article` (`id`, `name`, `time`, `img`, `content`) VALUES (1, '狗狗胆子特别小 怎样训练狗狗的胆量', '2025-11-22 22:25:17', 'http://127.0.0.1:9090/web/download/75078bc4221045c9b319ad4483d5b341.jpeg', '<p style=\"text-indent: 2em; text-align: start;\">一般胆小的狗狗很容易被周围的声音或者事情吓到，可以试试给它提供一个垫子，让它觉得那是安全的地方，它可以在这里躺下来或者专注于指令，能让它的情绪慢慢平静下来。改变狗狗胆小的性格，需要循序渐进的改变，切勿心急。</p><p style=\"text-align: center;\"><img src=\"https://www.bobocw.com/uploads/ueditor/image/20220715/1657894542191216.jpeg\" alt=\"狗狗胆子特别小 怎样训练狗狗的胆量\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em; text-align: start;\">狗狗喜欢有规律的生活。如果主人不断改变它们的生活规律和规则，这会让容易紧张的狗变得更加紧张。所以主人要尽量保持它日常生活规则的不变，可以让狗狗得以放松，在家里会相对自在舒服。</p><p style=\"text-indent: 2em; text-align: start;\">有研究表明，演奏古典音乐可以使狗狗平静下来。另外，按摩也是种让狗狗放松的好方法。不过胆小的狗狗可能需要一段时间的适应，才能接受主人的按摩，一旦它意识到这种操作的舒服性，它就会喜欢上这个狗狗按摩法。</p>');
INSERT INTO `article` (`id`, `name`, `time`, `img`, `content`) VALUES (2, '小奶狗好脏 可以给它洗澡吗', '2025-11-22 22:31:29', 'http://127.0.0.1:9090/web/download/dd5bd41a8b654c2dbe0b8523528c0923.jpeg', '<h5>小奶狗并不可以洗澡，在小奶狗满了两个月之后，最好是在疫苗驱虫都做完后再洗澡，需要多多注意小奶狗的健康问题，在给小奶狗洗澡的时候，要注意清洗的方法。</h5><p style=\"text-indent: 2em;\">小奶狗一般需要一个多月的时候能洗澡，毕竟刚出生的狗狗体质是很弱的，这个很容易造成狗狗感冒。严格来说，当幼犬还没有正常断奶，没有安全的度过疫苗观察期之前都是不能盲目给狗狗洗澡的。因为，此时的幼犬呼吸系统还很脆弱，身体抵抗力也很弱。如果贸然的给宠物狗洗澡，很容易就着凉生病的。记住，幼犬生病是一件非常麻烦的事情，感冒很容易就转变成肺炎，如果转成小叶型肺炎那情况就很糟糕了，很有可能会威胁幼犬的生命安全。</p><p style=\"text-align: center;\"><img src=\"https://www.bobocw.com/uploads/ueditor/image/20220702/1656693309192088.jpeg\" alt=\"小奶狗好脏，可以给它洗澡吗？\" data-href=\"\" style=\"\"></p><p><br></p><p style=\"text-indent: 2em;\">此外，当幼犬还在疫苗观察期间，也不能给幼犬洗澡，因为洗澡引起感冒而造成幼犬身体抵抗力下降，轻则会造成免疫的失败，重则由于疫苗本身属于弱化病毒，还有危及生命的危险。所以，要想给幼犬洗澡，还是等狗狗安全度过疫苗观察期再说吧。</p><p style=\"text-indent: 2em;\">而且，给幼犬洗澡一定要特别注意，要在温暖的室内，如果环境很潮湿阴冷，那么就暂时不要给狗狗洗澡了。可以尝试给狗狗擦擦身体，保持狗狗身体干净即可。此外，在给幼犬洗完澡之后一定要记得用吹风机将湿漉的毛发彻底吹干，这样幼犬才不容易感冒生病哦。</p><p><br></p>');
INSERT INTO `article` (`id`, `name`, `time`, `img`, `content`) VALUES (3, '听说折耳猫是缺陷 每天都会很痛苦吗', '2025-11-22 22:32:51', 'http://127.0.0.1:9090/web/download/58846c6a94184be4a6a1ef6ee85e039e.jpeg', '<p style=\"text-indent: 2em;\">折耳猫不会每天都很痛苦，折耳猫只是发生骨骼疾病的几率更大，但折耳猫没有发病的跟正常猫咪是没有区别的。如果折耳猫已经出现骨骼疾病，那么猫真的是每天生活在痛苦中，猫的疼痛耐受力很强，主人可能发现不了。主人可以定期带折耳猫去医院检查猫是否生病，也可以给折耳猫补钙预防。</p><p style=\"text-indent: 2em;\">饲养折耳猫，要做好各种清洁工作以保护猫咪免受寄生虫和其他疾病的侵害。每天给猫咪梳毛，定期清洁眼睛卫生，每周定期刷牙，避免口腔疾病，要修剪指甲，修指甲之间的毛，保证它的正常生活。</p><p style=\"text-align: center;\"><img src=\"https://www.bobocw.com/uploads/ueditor/image/20220702/1656694682625092.jpeg\" alt=\"听说折耳猫是缺陷？每天都很痛苦吗？\" data-href=\"\" style=\"\"></p><p><br></p><p style=\"text-indent: 2em;\">定期给猫用化毛膏，帮助清理肠胃中难以消化的毛球，减少胃肠道不适的风险，并帮助猫吐出毛球。</p><p style=\"text-indent: 2em;\">猫在喂养时需要特别注意，幼猫不应该喂牛奶和硬的食物，以免引起猫腹泻或胃肠消化不良。为猫咪准备专业的猫食，然后搭配新鲜蔬菜或白开水煮的鸡或牛肉混合，以保证猫咪的营养平衡。</p><p style=\"text-indent: 2em;\">饲养时，主人应主动引导猫做适当的运动，在闲暇时陪伴猫玩耍，相互交流，增强和猫的感情，也要让猫适当地锻炼。</p>');
INSERT INTO `article` (`id`, `name`, `time`, `img`, `content`) VALUES (4, '狗够是靠什么辨别方向的 “感觉”也是一种方法', '2025-11-22 22:33:25', 'http://127.0.0.1:9090/web/download/c7c96ba35bf0451a92a211ac504cdae3.jpeg', '<h4>视觉、听觉、嗅觉、触觉是狗狗辨别主人、辨别方向的主要方式，当然还有另一种方式就是“感觉”，感觉就是家对狗狗的感觉，狗狗对家的感觉，两者是互通的，即使相隔很远也能感知方向。</h4><h3>视觉</h3><p style=\"text-indent: 2em;\">很多对狗狗有些了解的人认为狗狗的视觉不好，不能分辨颜色，甚至是色盲，这样的观点是不够准确的。其实狗狗是能分辨色彩的，站在人类的角度来说，狗狗的色彩世界是很奇怪的;狗狗对眼睛的调节能力比人类差，但视野很开阔，能看得比人类更远，加上头部转动非常灵活，视力范围所到之处，它基本上都能感知。</p><h3>听觉</h3><p style=\"text-indent: 2em;\">其实狗狗在很小的时候就已经从听觉上认定了主人，将主人的声音信息记录在自己的大脑里并留下了深刻的印象，从说话声音的音色、音调，就能清楚地辨别主人和陌生人;这种听觉的记忆是长久的，几十年或一生都会记住这个信息，当在远处或近处听到主人声音时，会立马分辨出来。</p><p><img src=\"https://www.bobocw.com/uploads/ueditor/image/20220701/1656670798127388.jpeg\" alt=\"狗够是靠什么辨别方向的？“感觉”也是\" data-href=\"\" style=\"\"/></p><h3>嗅觉</h3><p style=\"text-indent: 2em;\">狗狗的嗅觉细胞非常发达，就2亿多个嗅觉细胞，一般是人类的40倍左右，能对一些化学物品准确的辨识，空气中的有害气体规避以及失落物品的查找。狗狗在进食时，往往先会嗅一下， 辨别能否进食。还有一个非常重要的功能，那就是辨别方向，狗狗通过留下的尿液，找到回家的路。狗狗不仅能从嗅觉上 分辨主人，还能辨别方位，寻找猎物，寻找食物等。</p><h3>触觉</h3><p style=\"text-indent: 2em;\">狗狗脚底分布很多神经末梢，能很好地感知外部世界温度的变化，也能很好地感知外部信息;当有人走动时，就会记录走动的频率和次数，从而记住这个人。狗狗皮毛也非常的敏感，主人抚摸的方式和方法，触摸肌肤时也会被狗狗记录在内。因此，触觉也是辨别主人的方式之一。</p>');
INSERT INTO `article` (`id`, `name`, `time`, `img`, `content`) VALUES (5, '泰迪犬要具备基本训练 新手必学', '2025-11-22 22:36:45', 'http://127.0.0.1:9090/web/download/d40eef93b2d74199a4de858ea2842b91.jpeg', '<h5>训练不等于训斥，这点非常重要。在人类社会里，对小孩使用训斥的方法，容易让他们产生逆反心理，更何况人的语言跟狗是说不通的。因此用训斥的方法来训练狗，是很难达到效果的，而且使狗会有这样一种感觉，就是人不值得信赖的。当然养了狗狗后，很多人都想把狗狗训练得更乖巧可爱。那么，要如何让泰迪学会基本的训练呢？</h5><p style=\"text-indent: 2em;\"><strong>1、训练泰迪坐下</strong></p><p><strong>一、训练泰迪坐下</strong></p><p style=\"text-indent: 2em;\">其实<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗狗是很聪明的，但是训练师需要时机和方法的。训练的同时加一点零食去奖励狗狗，或许会有很好的效果哦。我们需要观察<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>宝宝的动作，刚好它坐下，或者是主人按<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗狗屁股坐下的时候，你就用一句口号来叫狗狗坐下，例如：坐下或者SIT。</p><p style=\"text-indent: 2em;\">如果<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗狗做到了要求，我们就奖励一点狗粮或者零食给它吃。吃完之后又继续以同样的做法叫它，它或许会有些不理解，但是当动作重复多了后，狗狗就会慢慢懂得是什么意思了。当然在做得同时，主人尽量不要缺乏奖励哦，有了奖励<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗狗才会更加卖力的学习。</p><p><img src=\"https://www.bobocw.com/uploads/ueditor/image/20230104/1672824021186441.jpeg\" alt=\"泰迪犬要具备基本训练 新手必学\" data-href=\"\" style=\"\"/></p><p style=\"text-align: left;\"><strong>二、训练泰迪不许动</strong></p><p style=\"text-indent: 2em; text-align: left;\">让狗狗原地坐着比训练狗狗其它的技能都是比较难的，因为狗狗天生就是活泼，好动的。想让狗狗坐在原地不动，必须要先训练狗狗的定力。当然，首先得让狗狗懂得听命令坐着，等狗狗坐下的时候。</p><p style=\"text-indent: 2em; text-align: left;\">主人可以在狗狗的眼前走来走去，一般刚开始，狗狗会很容易就起身，因为当狗狗看到主人走来走去的时候，它就会有种想法想跟在之人的后面。因此在狗狗起身前，主人要立刻制止，让它继续坐着。直到下命令叫它“起身”的时候，才能让狗狗起来。当然在训练过程中也是少不了奖励的，主人要有奖励狗狗才会有动力哦。</p><p style=\"text-indent: 2em;\"><br></p><p><img src=\"https://www.bobocw.com/uploads/ueditor/image/20230104/1672824078122062.jpeg\" alt=\"泰迪犬要具备基本训练 新手必学\" data-href=\"\" style=\"\"/></p><p><strong>三、泰迪站着走（不宜时间过长，容易造成的腰椎伤害）</strong></p><p style=\"text-indent: 2em;\">很多人都知道<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗狗是最会学人走路的，那么是怎么训练出来的呢？其实训练狗狗站着走路方法很简单，你可以手上拿上一些狗狗最爱吃的食物，然后双手举得高高的，但要在狗狗站起来的高度之上，然后示意狗狗让它尝试站立起来去取食物。</p><p><img src=\"https://www.bobocw.com/uploads/ueditor/image/20230104/1672824343133196.jpeg\" alt=\"泰迪犬要具备基本训练 新手必学\" data-href=\"\" style=\"\"/></p><p style=\"text-indent: 2em;\">在刚开始训练的时候，<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>能成功的站立起来后，不要在马上给它食物。而是，你要拿着食物慢慢的后退，如此来引导狗狗慢慢的向前走，等到训练一段时间后，你会发现狗狗慢慢地能站立，并且可以短时间行走了哦。这时的主人就应该奖励<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗狗吃点零食了，随着训练有了一定的时间，也要慢慢训练狗狗站立更长的时间，然后就训练它站立行走路。</p><p><strong>要点补充：</strong></p><p style=\"text-indent: 2em;\">1、“站立”这个动作，时间过长的话，容易造成<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>小狗的腰椎伤害，因此不要让狗狗太长时间立正或持续立正的时间太久。</p><p style=\"text-indent: 2em;\">2、如果狗狗不能本能地直起来，如何才能教会它呢？您可以通过狗链来控制，但是用力不可过大，别把狗狗勒得喘不过气来；也不可太小，让它无法保持站立的姿势而倒下。时间和力度的把握都非常重要。</p><p style=\"text-indent: 2em;\">3、如果狗狗训练时不太听话，你可以试着用一点儿好吃的，比如狗狗零食，引诱它站起来，跟狗狗交谈，慢慢地延长<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗狗直立的时间。</p><p><img src=\"https://www.bobocw.com/uploads/ueditor/image/20230104/1672824584130412.jpeg\" alt=\"泰迪犬要具备基本训练 新手必学\" data-href=\"\" style=\"\"/></p><p><strong>四、指定的地方大小便</strong></p><p style=\"text-indent: 2em;\">我们都知道，<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗不喜欢在沾有自己尿臭的地方大小便，即使报纸和厕纸的表面已经干了它们也不愿意。聪明的<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗会凭着自己敏锐的嗅觉，当闻到有种异味的时候，便会认为这里已经脏了，而就会到其它处所排泄。所以在训练的<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>过程中需要特别注意，针对<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗这种特殊的性格，要制定出有效的训练方法。</p><p style=\"text-indent: 2em;\">首先，<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗的训练应该在5月龄左右开始。训练的时候要密切关注狗狗的一举一动，详细的了解<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗的饮食习惯和排便规律。其次家长需要为狗狗准备一个固定的，干净的狗厕所。在市面上购买或者是自己制作都可以，只要狗狗不嫌弃。</p><p style=\"text-indent: 2em;\">每次在<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗起床、饮食过后30分钟、饮水过后15分钟左右，都要密切关注它的行为活动。当发现<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗不断转动身子，用嘴巴在地面上到处嗅的时候，就表明它需要排便了，它正在寻找满意的厕所。此时，主人就可以引导<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗去专业的狗厕所，然后鼓励它排便。</p><p style=\"text-indent: 2em;\">注意了：在训练的过程中，家长千万不能随意打骂狗狗。特别是发现狗狗在其它地方排便之后，要训斥教育，但是千万不能随意辱骂殴打。家长训练<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>狗最基本的原则是奖罚分明，积极引导，及时纠正错误。</p><p><img src=\"https://www.bobocw.com/uploads/ueditor/image/20230104/1672824001622805.jpeg\" alt=\"泰迪犬要具备基本训练 新手必学\" data-href=\"\" style=\"\"/></p>');
INSERT INTO `article` (`id`, `name`, `time`, `img`, `content`) VALUES (6, '为什么要办狗证 狗证有什么用', '2025-11-22 22:37:51', 'http://127.0.0.1:9090/web/download/2284004ea26243e084974ba35dba392d.jpeg', '<h5>狗证是一种凭证，就像人的身份证一样，证明狗狗的身份，并作为一种合法的养狗证明。目前养狗都需要办狗证，若不办狗证根据各城市的规定不同，可能会处以罚款或者没收犬只。</h5><p style=\"text-indent: 2em;\">办理狗证之前需要先去可以开狂犬免疫证的医院接种疫苗，然后再去相关机构办理狗证。</p><p style=\"text-align: center;\"><img src=\"https://www.bobocw.com/uploads/ueditor/image/20220715/1657895161393631.jpeg\" alt=\"为什么要办狗证 狗证有什么用\" data-href=\"\" style=\"\"></p><p style=\"text-indent: 2em;\">办理狗证不仅仅是便于相关部门对狗狗以及养狗人这一群体的管理，降低一些潜在的风险和安全隐患，推进文明养犬的进程。同时，狗证也是法律承认了狗狗的合法性，也更能保障狗狗的安全，比如狗狗走丢后，可以让派出所帮忙寻找，或者他人捡到狗狗也能方便联系到主人，这样可以避免狗狗在外流浪受苦甚至遭遇危险。</p><p><br></p>');
COMMIT;

