-- ----------------------------
-- Table structure for pet
-- ----------------------------
DROP TABLE IF EXISTS `pet`;
CREATE TABLE `pet` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '宠物名称',
  `age` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '年龄',
  `sex` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '性别',
  `health` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '健康状态',
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片',
  `img_list` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更多图片',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '其他说明要求',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所在地',
  `time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发布时间',
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '领养状态',
  `type_id` int DEFAULT NULL COMMENT '宠物类别id',
  `user_id` int DEFAULT NULL COMMENT '发布人id',
  `category` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发布方',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统宠物管理';

-- ----------------------------
-- Records of pet
-- ----------------------------
BEGIN;
INSERT INTO `pet` (`id`, `name`, `age`, `sex`, `health`, `img`, `img_list`, `content`, `address`, `time`, `status`, `type_id`, `user_id`, `category`) VALUES (1, '橘子', '2个月左右', '公', '1,2', 'http://127.0.0.1:9090/web/download/7011196e691c40fb984e4fac9b4cc5b7.jpg', 'http://127.0.0.1:9090/web/download/1a3fe16dacd5438286c2d269cc9f4af2.jpg', '<p style=\"text-align: start;\">被救助的小猫2个月左右，健康，被锁在一家肮脏商店的小笼子里。</p><p style=\"text-align: start;\">他非常可爱，想要一个美好的家。在上海。请联络 Ben. 15618928329</p>', '上海市/市辖区/徐汇区', '2025-11-23 23:20:32', '待领养', 10, NULL, '官方');
INSERT INTO `pet` (`id`, `name`, `age`, `sex`, `health`, `img`, `img_list`, `content`, `address`, `time`, `status`, `type_id`, `user_id`, `category`) VALUES (2, '团团', '5个月左右', '母', '2', 'http://127.0.0.1:9090/web/download/88f4de627a244295bd16d68d452f58a5.jpg', 'http://127.0.0.1:9090/web/download/fce7556d295742fabfe3a775e9190178.jpg', '<ol><li style=\"text-align: left;\">定期上门回访</li><li style=\"text-align: left;\">定期视频回访</li><li style=\"text-align: left;\">拒绝笼养</li><li style=\"text-align: left;\">拒绝二次抛弃</li><li style=\"text-align: left;\">不可转送</li><li style=\"text-align: left;\">定期免疫</li></ol><p style=\"text-align: left;\">团团是求助人帮助我们救助的一只小狗，前主人经常打骂不给饭吃，现在比较怕生，需要有耐心的人引领走出阴影。</p>', '山东省/泰安市/泰山区', '2025-11-23 23:29:14', '待领养', 11, NULL, '官方');
INSERT INTO `pet` (`id`, `name`, `age`, `sex`, `health`, `img`, `img_list`, `content`, `address`, `time`, `status`, `type_id`, `user_id`, `category`) VALUES (3, '水管', '3个月', '母', '2', 'http://127.0.0.1:9090/web/download/e5fc033f1e384e2f8d44fb3ee82ae8e2.jpg', 'http://127.0.0.1:9090/web/download/13456b3bba8d4b61b760622f59072c4c.jpg', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\">流浪猫，卡在救助人家单元楼外竖着的雨水管里了，把它救了后发现它前面一个爪子受伤了，现在伤已经好了，寻找好归宿。</span></p>', '河北省/廊坊市/广阳区', '2025-11-23 23:41:01', '待领养', 10, NULL, '官方');
INSERT INTO `pet` (`id`, `name`, `age`, `sex`, `health`, `img`, `img_list`, `content`, `address`, `time`, `status`, `type_id`, `user_id`, `category`) VALUES (4, 'lucky', '4岁', '母', '1,2', 'http://127.0.0.1:9090/web/download/ad28632073704b518b49ebb2f30d534a.jpg', 'http://127.0.0.1:9090/web/download/a549d6a9489a4af6ac8a48a6ab5b34cf.jpg,http://127.0.0.1:9090/web/download/b1eb78b47cc84ed6a93d2298e3b82919.jpg', '<p>因求助人生病，寻找领养，<span style=\"color: rgb(102, 102, 102);\">未绝育未生育，称的体重是5.9公斤。</span></p>', '广东省/汕头市/龙湖区', '2025-11-26 01:42:47', '已领养', 1, NULL, '官方');
INSERT INTO `pet` (`id`, `name`, `age`, `sex`, `health`, `img`, `img_list`, `content`, `address`, `time`, `status`, `type_id`, `user_id`, `category`) VALUES (5, 'miumiu', '3岁', '母', '1,2,3', 'http://127.0.0.1:9090/web/download/bf95e8d1114d42689f68982551dff188.jpg', 'http://127.0.0.1:9090/web/download/075072fd9de04d799704a82f95eb43da.jpg', '<p>测试测试</p>', '天津市/市辖区/河东区', '2025-11-26 01:45:48', '待领养', 7, NULL, '官方');
INSERT INTO `pet` (`id`, `name`, `age`, `sex`, `health`, `img`, `img_list`, `content`, `address`, `time`, `status`, `type_id`, `user_id`, `category`) VALUES (6, '福福', '6个月', '公', '1,2', 'http://127.0.0.1:9090/web/download/f1930bbef3254889b303abc324923011.webp', 'http://127.0.0.1:9090/web/download/0d8a9f69f7004410b16520e1141f3142.webp', '<p style=\"text-indent: 2em; text-align: start;\">让流浪的小动物都能有一个好的归宿</p><p style=\"text-indent: 2em; text-align: start;\">您的领养，也是帮助流浪动物的一种方式。</p>', '江苏省/无锡市/惠山区', '2025-11-26 01:51:05', '已领养', 3, NULL, '官方');
INSERT INTO `pet` (`id`, `name`, `age`, `sex`, `health`, `img`, `img_list`, `content`, `address`, `time`, `status`, `type_id`, `user_id`, `category`) VALUES (7, '小九', '1岁', '母', '2,3', 'http://127.0.0.1:9090/web/download/26d2d6160c9e4bbcb16bcfa608ce4693.jpg', 'http://127.0.0.1:9090/web/download/0247aa066c1e4061a40d72e465122d9f.jpg', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\">这是我见过最温顺的小猫，洗澡、做肛拭子的时候都不伸爪，非常亲人，经常蹭蹭，稍微有点胆小。小区楼道捡到的小猫，性格温顺，发现时外观整洁，应是走失家猫。发布</span><a href=\"http://www.bagong.cn/findpet\" target=\"_blank\" style=\"text-align: start;\">寻猫</a><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\">启示后，目前未曾有人认领。因家中猫太多无法自养，寻求有缘人</span><a href=\"http://www.bagong.cn/lingyang\" target=\"_blank\" style=\"text-align: start;\">领养</a><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\">。目前已做体检、洗澡、驱虫，眼部有轻微泪痕，已用妥布霉素治疗。</span></p>', '江苏省/南京市/江宁区', '2025-12-07 15:25:10', '已领养', 7, 1, '个人');
INSERT INTO `pet` (`id`, `name`, `age`, `sex`, `health`, `img`, `img_list`, `content`, `address`, `time`, `status`, `type_id`, `user_id`, `category`) VALUES (8, '团团', '6个月', '母', '2', 'http://127.0.0.1:9090/web/download/1e39777ab73e4de5971895d7e3da7596.jpg', 'http://127.0.0.1:9090/web/download/30b3f16bfd0f4713a51d1dabe0b61fd3.jpg', '<p><span style=\"color: rgb(102, 102, 102); font-size: 22px;\">2022年9月28日出生的团团，她的妈妈是一只被救助的小流浪。性格胆小的她，不易亲近人，和人类若即若离也是好多猫猫的一种陪伴方式，团团也是这样，她会和你互动玩猫棒，但在没有找到安全感之前，她总会藏起来。希望找到一个爱她给予她陪伴不离不弃的家人。测试</span></p>', '甘肃省/兰州市/安宁区', '2025-12-07 15:26:57', '已领养', 10, 1, '个人');
INSERT INTO `pet` (`id`, `name`, `age`, `sex`, `health`, `img`, `img_list`, `content`, `address`, `time`, `status`, `type_id`, `user_id`, `category`) VALUES (10, '乐豆', '1岁', '公', '2', 'http://127.0.0.1:9090/web/download/f261c10b7ecb4afd9c9a4d59002aafa9.jpg', 'http://127.0.0.1:9090/web/download/b8cfdfdcffff41c88e13cdc44dd81190.jpg', '<p><span style=\"color: rgb(102, 102, 102); font-size: 22px;\">经过救助康复的小狗狗,很活泼.很可爱粘人的!</span></p>', '天津市/市辖区/河西区', '2025-12-07 15:45:54', '已领养', 1, 1, '个人');
COMMIT;

-- ----------------------------
-- Table structure for rescue
-- ----------------------------
DROP TABLE IF EXISTS `rescue`;
CREATE TABLE `rescue` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '救援标题',
  `user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '通报人称呼',
  `phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '通报类型',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '位置区域',
  `time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发生时间',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '情况描述',
  `user_id` int DEFAULT NULL COMMENT '用户id',
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理状态',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='宠物救援管理';

