INSERT INTO `rescue` (`id`, `name`, `user_name`, `phone`, `description`, `address`, `time`, `content`, `user_id`, `status`) VALUES (4, '我希望可以帮我救助一只小狗', '王兰花', '18888888888', '动物受困', '北京市/市辖区/东城区', '2025-12-08 15:45:48', '<p>我看到一只小狗他腿断了，我希望可以帮忙救助！感谢！</p><p><img src=\"http://127.0.0.1:9090/web/download/b3d0bf65c0b0464ca724e1299996601c.jpg\" alt=\"\" data-href=\"\" style=\"width: 293.89px;height: 335.26px;\"/></p>', 1, '已取消');
INSERT INTO `rescue` (`id`, `name`, `user_name`, `phone`, `description`, `address`, `time`, `content`, `user_id`, `status`) VALUES (5, '我看到一堆小猫，希望救助一下', '王兰花', '18888888888', '动物受困', '北京市/市辖区/东城区', '2025-12-09 19:04:44', '<p>我看到很多小猫受困了，可以帮忙救助一下吗</p><p><img src=\"http://127.0.0.1:9090/web/download/e919affc9e694c7aa6b2b8bf5ae41f38.jpg\" alt=\"\" data-href=\"\" style=\"width: 366.89px;height: 418.52px;\"/></p>', 1, '已援助');
COMMIT;

