-- ----------------------------
-- Table structure for trend
-- ----------------------------
DROP TABLE IF EXISTS `trend`;
CREATE TABLE `trend` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标题',
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '内容',
  `time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='团队动态管理';

-- ----------------------------
-- Records of trend
-- ----------------------------
BEGIN;
INSERT INTO `trend` (`id`, `name`, `img`, `content`, `time`) VALUES (1, '猫只领域护理计划', 'http://127.0.0.1:9090/web/download/18f8f18ae3aa48ebaad1c71fc46e1927.jpg', '<p style=\"text-align: start;\">自2000 年8 月起，爱护动物协会的「猫只领域护理计划」正式展开，集合爱协的资源和爱猫人士之力，以人道方法控制本港日益上升的街猫数量。</p><p style=\"text-align: start;\">经过二十五年来的努力，爱协的「猫只领域护理计划」一共为超过86,000 只街猫进行绝育（截至2025年），协助降低人道毁灭率，同时改善市区环境。</p><p style=\"text-align: start;\"><br></p><p style=\"text-align: start;\"><img src=\"http://127.0.0.1:9090/web/download/67f73b5837a14f6fae5460f462ec48a5.png\" alt=\"\" data-href=\"\" style=\"\"></p><p>避免<strong>超过100 万</strong>只幼猫出生</p><p><img src=\"http://127.0.0.1:9090/web/download/acac087138e74d1fbc4ebe9e48120129.png\" alt=\"\" data-href=\"\" style=\"\"/></p><p>管理<strong>超过2,200</strong>个猫只领域</p><p><img src=\"http://127.0.0.1:9090/web/download/d592237bce354d18a86aa35bbdd1fa31.png\" alt=\"\" data-href=\"\" style=\"\"/></p><p><strong>超过1,298 位</strong>注册义务护理员</p><p><img src=\"http://127.0.0.1:9090/web/download/845fbee1d2824ed59e363b07cfab9f11.png\" alt=\"\" data-href=\"\" style=\"\"/></p><p>最高峰时，我们每年要进行<strong>6,000</strong>多次绝育手术。</p><p><img src=\"http://127.0.0.1:9090/web/download/20077de313f74bf9ae0249e8e5977ab5.png\" alt=\"\" data-href=\"\" style=\"\"/></p><p><strong>超过86,000</strong>只街猫已绝育</p><p><br></p><p>猫在港人心目中，占一个很特别的位置。有人极爱，经常于城内四出搜寻它们的足迹，并用镜头拍下它们的一举手一投足；亦有人对其憎厌，认为它们是滋扰的源头。在香港这个人多挤逼的城市里，住著成千上万的流浪猫，它们机警聪明，且有顽强的生命力和惊人的繁殖能力。</p><p>然而流浪的日子非常艰苦，街猫更经常受到疾病、被猎食和意外的威胁，每天为生存而奋力挣扎，为争夺地盘和配偶而打斗受伤。另外，为了向同类宣示主权，它们更不时四处号叫和尿溺，为居民带来困扰，因此「猫只领域护理计划」便深入社区，为这些问题提供人道的解决方案。</p>', '2025-11-22 22:44:28');
INSERT INTO `trend` (`id`, `name`, `img`, `content`, `time`) VALUES (2, '流动绝育车', 'http://127.0.0.1:9090/web/download/e203bdb9b75f426e8aa6c00e1601c4eb.png', '<p><br></p><h2>流动绝育车</h2><p><br></p><p>动物数量过剩的问题于新界和离岛等地尤其普遍，居民多以「自由放养」的形式饲养动物，其中已绝育的少之又少，又任由它们四处游荡。</p><p>这造成了每年数以千计的幼犬和幼猫出生，当中大部分无人认养，结果它们不是被丢到街上，便是被遗弃于垃圾站。这些无家可归既没有接种疫苗的动物在街上流浪，每天于受伤、饥饿、患病、交通意外及被捕猎的风险下挣扎求存，甚至于不人道的情况下死去。</p><p><img src=\"http://127.0.0.1:9090/web/download/4aeda9e30ee14d2bb5277b0af815a5ba.png\" alt=\"\" data-href=\"\" style=\"width: 593.46px;height: 377.73px;\"/></p><h2>提供廉宜和便利的绝育服务</h2><p><br></p><p>流动绝育车是一辆流动手术医疗车，让我们深入乡村地区进行教育工作，并向居民宣传爱协的动物绝育计划，带出绝育能有效控制猫狗数量及改善动物健康等好处。</p><p>第一代的流动绝育车由何东爵士慈善基金及EXTRA TRADING COMPANY LTD 捐赠，并于2020 年退伇，而新的流动绝育车则由吴崇安慈善基金慷慨支持，为偏远地区的居民提供廉宜的狗只和猫只绝育手术服务。</p>', '2025-11-22 22:52:56');
INSERT INTO `trend` (`id`, `name`, `img`, `content`, `time`) VALUES (3, '唐狗绝育计划', 'http://127.0.0.1:9090/web/download/51ca50efeebd422f90668202e70760b4.png', '<p><br></p><h2>唐狗绝育计划</h2><p><br></p><p>我们不难发现有不少狗只在建筑工地及乡村内游荡，自由交配。在这些狗群中，成犬很易受到疾病、意外及营养不良的威胁，而幼犬于五至六个月大便可以瀪殖，导致更多流浪狗只出现，因此爱协于2013年亦特别为有负责人的唐狗推出了「唐狗绝育计划」，透过免费绝育服务，去控制社区狗只数量。</p><p>市民和狗主均可预约，带同唐狗前往爱协的<a href=\"https://www.spca.org.hk/zh-hant/contact/spca-centres/the-spca-jockey-club-centennial-centre/\" target=\"\"><strong>青衣中心</strong></a>接受免费绝育服务。合资格狗只必需为：</p><ul><li>唐狗（混种狗）</li><li>年龄介乎4个月至7岁之间</li><li>身体健康（不肥胖）</li></ul><p>为鼓励狗主成为一个尽责的主人，在手术当天爱协亦会同时提供免费狂犬病疫苗注射及豁免植入AVID晶片及申请牌照的费用。</p><p><br></p><p style=\"text-align: center;\"><strong>如有意为唐狗预约绝育服务，请致电</strong><br><a href=\"tel:25935438\" target=\"\"><strong>2593 5438</strong></a>预约或<a href=\"tel:22325513\" target=\"\"><strong>2232 5513</strong></a>联络<a href=\"https://www.spca.org.hk/zh-hant/what-we-do/animal-welfare/animal-welfare-campaigns-and-programs/animal-welfare-vehicle/\" target=\"\"><strong>爱协流动绝育车</strong></a>。</p><p style=\"text-align: center;\"><br></p><p>条款与细则:</p><ul><li>唐狗之定义为非纯种犬或非明显之纯种犬混种犬。</li><li>如有任何关于狗只之品种异议，爱协兽医拥有最终决定权。</li><li>如犬只未能符合唐狗绝育计划之资格，阁下仍可进行绝育手术，而手术则按正常收费。</li><li>由于每日所能安排之手术名额有限，绝育手术将以先到先得的方法分配。</li><li>主人或负责人必须于预约时指明使用唐狗免费绝育计划，此计划并不接受手术当天或手术后申请。</li><li>如未有于手术预约的当天应诊或滥用此服务，该申请人或狗主将来可能不会再被接受申请此项目。</li><li>经本计划接受绝育的狗只必须已植入晶片，如果狗只本身未有植入晶片和领取狗牌，又不打算进行相关程序，爱协则会为狗只植入ISO晶片，仅为识别狗只之用。此为计划的必要条款。</li><li>爱协保留更改条款及细则之权利，而不会作任何通知。如有争议，爱协将保留最终决定权。</li><li>本条款与细则为英文版本译本，如中、英文两个版本有任何抵触或不相符之处，应以英文版本为准。</li></ul>', '2025-11-22 23:03:15');
INSERT INTO `trend` (`id`, `name`, `img`, `content`, `time`) VALUES (4, '这或许是我们离《反虐待动物法》最近的一次 ', 'http://127.0.0.1:9090/web/download/f7265f9b42dd4aa7b8868e0d6ebe6986.jpeg', '<p style=\"text-align: left;\"><span style=\"font-size: 16px;\">10月27日，司法部正式启动《2026年度立法项目建议征集》，征集期截至2025年</span><span style=\"font-size: 16px;\"><strong>11月26日</strong></span><span style=\"font-size: 16px;\">。</span></p><p style=\"text-align: left;\"><img src=\"https://q8.itc.cn/q_70/images03/20251120/55a3cdfbfde84a6983530109dcebbef0.png\" alt=\"\" data-href=\"\" style=\"height: auto;\"></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">这是一个关键的政策窗口期。基于近年来频发的虐待动物个案、网络平台的治理实践以及强烈的公众关注，它基金今年将聚焦</span><span style=\"font-size: 16px;\"><strong>未成年人保护</strong></span><span style=\"font-size: 16px;\">与</span><span style=\"font-size: 16px;\"><strong>社会治理</strong></span><span style=\"font-size: 16px;\">，向司法部提交两项重点立法建议。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">制定一部专门的《反虐待动物法》道阻且长，但我们可以采取更务实、更聚焦的策略，推动法律的渐进式完善。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">我们相信，为虐待动物行为及其网络传播</span><span style=\"font-size: 16px;\"><strong>设定法律底线，不仅是保护动物，更是在守护青少年的心理健康，维护我们共同的社会秩序。</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">建议一：修订《未成年人网络保护条例》，为下一代筑起“防火墙”</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">我们建议，在《未成年人网络保护条例》及相关配套文件中，将</span><span style=\"font-size: 16px;\"><strong>“以宣传或鼓励虐待动物为目的发布虐待动物的图片、影像或声音”</strong></span><span style=\"font-size: 16px;\">明确列入从严管控内容，纳入网络暴力和有害信息治理体系。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>为什么必须行动？</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">网络上泛滥的虐待动物内容，正成为侵蚀未成年人心理健康的“精神毒瘤”。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>诱导模仿与参与：</strong></span><span style=\"font-size: 16px;\">更令人担忧的是，未成年人正从被动观看者变成主动参与者。中南财经政法大学动物法研究所的调研发现，在一些虐待动物的QQ群中，00后成员占比竟高达三分之一。从虐待仓鼠到虐杀猫狗，孩子们在扭曲的“亚文化”中，一步步将残忍内化。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>为什么可行？</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>已引起有关部门重视：</strong></span><span style=\"font-size: 16px;\">中央网信办多次将治理虐待动物内容纳入专项行动。2023年12月中央网信办“清朗·整治短视频信息内容导向不良问题”专项行动中，“虐待动物”列于“短视频展示不当行为问题”当中的</span><span style=\"font-size: 16px;\"><strong>【展示高危行为】</strong></span><span style=\"font-size: 16px;\">；2025年9月“清朗·整治恶意挑动负面情绪问题”专项行动中，明确将“虐待动物、自残自伤等极端行为的刺激图片视频”列为</span><span style=\"font-size: 16px;\"><strong>【挑起网络暴力戾气】</strong></span><span style=\"font-size: 16px;\">的重点整治内容。2025年5月，最高人民法院在未成年人保护“公开课”中，将“虐待动物的极端内容”明确列为对未成年人的“红色预警”。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">建议二：修订《治安管理处罚法》，让施暴者承担责任</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">我们建议，在《治安管理处罚法》中</span><span style=\"font-size: 16px;\"><strong>增设“虐待动物”处罚条款，清晰界定违法行为边界，并明确从重处罚的情形</strong></span><span style=\"font-size: 16px;\">，例如：以宣传或鼓励虐待动物为目的发布相关内容、通过虐待动物牟利、在公共场所实施或造成恶劣社会影响、多次实施、影响未成年人等。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>为什么必须行动？</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>扰乱公共秩序，违背公序良俗：</strong></span><span style=\"font-size: 16px;\">在社区、公园等公共场所实施的虐待行为，不仅直接伤害动物，也给目睹者，特别是儿童与老人，带来巨大的心理冲击和不安全感。这类行为破坏社区安宁，极易引发社会矛盾。网络传播的血腥、暴力内容，对广大网民造成精神污染和心理创伤，频繁引发网络对立和“人肉搜索”等非理性行为，扰乱网络生态。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>虐待动物是更严重暴力的“预警信号”：</strong></span><span style=\"font-size: 16px;\">大量研究证实，虐待动物与人类暴力，尤其是青少年暴力犯罪高度相关。北京航空航天大学的研究指出，暴力犯罪人群参与虐待动物的行为显著高于普通人群。漠视对动物的残忍，就是为社会埋下暴力的种子。将虐待动物纳入治安管理处罚，是从源头进行干预，筑牢社会安全的第一道防线。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>为什么现在可行？</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>已有执法实践：</strong></span><span style=\"font-size: 16px;\">近年来，基层执法部门已开始探索使用《治安管理处罚法》惩处虐待动物行为。2025年9月，北京一男子因在网络平台发布多条虐猫视频，被警方处以行政拘留十日、罚款五百元。同年8月，福建莆田一男子因大量虐杀猫咪并网络传播，被处以行政拘留十五日。在文号为“南公青行罚决〔2023〕1894号”的行政处罚案件中，决定书明确指出“被处罚人以各种残忍手段将多只猫虐待致死，并将虐猫致死视频发布于网络造成恶劣社会影响”，并依法作出处罚。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>暴露法律空白：</strong></span><span style=\"font-size: 16px;\">然而，法律适用仍存在不确定性。在上述个案中，常引用《治安管理处罚法》第二十六条第四项“寻衅滋事”条款，但并未明确提及“虐待动物”。在公众视野之外，仍有大量虐待动物案件立案困难、执法不了了之。增设专门条款，正是为了填补这一空白。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>为什么现在是推动修法的关键时刻？</strong></span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>保护未成年人刻不容缓：</strong></span><span style=\"font-size: 16px;\">虐待动物影像具有强烈的视觉冲击和模仿风险，持续影响一代人心理健康与价值观的形成。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>维护公序良俗与基层治理：</strong></span><span style=\"font-size: 16px;\">虐待动物事件极易在网络发酵，引发公众对立与线下冲突，显著抬高执法与社会治理成本。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>完善平台治理与依法行政：</strong></span><span style=\"font-size: 16px;\">当前法律标准不一、平台取证困难，亟需在更高位阶的法律中明确虐待动物内容的认定标准与平台的处置义务，让依法行政有据可循。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>展示国家文明形象：</strong></span><span style=\"font-size: 16px;\">将尊重生命、反对虐待写入法律，是与国际通行做法接轨，更是体现社会文明进步与法治现代化的重要标志。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>高度契合司法部征集重点：</strong></span><span style=\"font-size: 16px;\">我们的建议紧密围绕司法部本次征集的“增进民生福祉、深入推进依法行政、推动绿色发展、加强涉外法治建设”等重点方向，具备充分的现实必要性与法理可行性。</span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\">▼</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>我们将在征集期内提交上述建议。</strong></span><span style=\"font-size: 16px;\">同时，法律的完善离不开每一个人的声音。我们诚挚地邀请您，从自己的视角出发，向司法部投递您的意见，为推动政策进步一起发声。</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\"><strong>立即参与</strong></span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\">📅 意见递交截止日期</span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\">2025年11月26日</span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\">📮 信函邮寄</span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\">📧 电子邮箱</span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\">2026zjxmjy@moj.gov.cn</span></p><p style=\"text-align: center;\"><span style=\"font-size: 16px;\">📝 信件基本要素（建议）</span></p><p style=\"text-align: left;\"><span style=\"font-size: 16px;\">建议立法项目名称，必要性与可行性，拟解决的主要问题，拟确立的主要制度；并注明联系人与联系方式。（以单位名义提交请加盖公章）</span></p>', '2025-11-23 22:48:32');
COMMIT;

-- ----------------------------
-- Table structure for type
-- ----------------------------
DROP TABLE IF EXISTS `type`;
CREATE TABLE `type` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '种类名称',
  `origin` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原产地',
  `body` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '体型',
  `height` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身高',
  `hair` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '毛长',
  `lifespan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '寿命',
  `trainability` int DEFAULT NULL COMMENT '可训度',
  `shed` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '掉毛度',
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品种图片',
  `info` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '基本信息',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '更多详情',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='宠物种类管理';

-- ----------------------------
-- Records of type
-- ----------------------------
BEGIN;
INSERT INTO `type` (`id`, `name`, `origin`, `body`, `height`, `hair`, `lifespan`, `trainability`, `shed`, `img`, `info`, `content`) VALUES (1, '泰迪犬', '德国', '小型', '20-38cm', '长毛', '12-19年', 4, '2', 'http://127.0.0.1:9090/web/download/eb818406b4ad413c86e37e972a0fd6fa.jpeg', '泰迪犬其实是贵宾犬的一种美容方式。贵宾是法国品种，一度被用作猎水鸟，19世纪和20世纪该品种达到其发展的顶峰，用作打猎、表演和陪伴。', '<p style=\"text-align: left;\">根据体型大小被分为四类，最受欢迎的是体型较小的品种：迷你<a href=\"https://www.bobocw.com/pet/48.html\" target=\"_blank\">贵宾犬</a>和玩具<a href=\"https://www.bobocw.com/pet/48.html\" target=\"_blank\">贵宾犬</a>。其中玩具<a href=\"https://www.bobocw.com/pet/48.html\" target=\"_blank\">贵宾犬</a>是体型最小的一种。<a href=\"https://www.bobocw.com/pet/48.html\" target=\"_blank\">贵宾犬</a>不脱毛，是极好的宠物犬。如果红色玩具<a href=\"https://www.bobocw.com/pet/48.html\" target=\"_blank\">贵宾犬</a>不剃胡须和嘴边的毛 可以长成动漫画里面<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>熊的模样</p><p style=\"text-align: left;\">所以红色玩具<a href=\"https://www.bobocw.com/pet/48.html\" target=\"_blank\">贵宾犬</a>又叫“<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>熊”。<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>属于<a href=\"https://www.bobocw.com/pet/48.html\" target=\"_blank\">贵宾犬</a>的一种美容方式。很多打着<a href=\"https://www.bobocw.com/pet/117.html\" target=\"_blank\">泰迪</a>贵宾旗号的<a href=\"https://www.bobocw.com/pet/48.html\" target=\"_blank\">贵宾犬</a>，其实为失格的<a href=\"https://www.bobocw.com/pet/48.html\" target=\"_blank\">贵宾犬</a>，一般都眼圆，耳位高。</p>');
INSERT INTO `type` (`id`, `name`, `origin`, `body`, `height`, `hair`, `lifespan`, `trainability`, `shed`, `img`, `info`, `content`) VALUES (2, '西高地犬', '苏格兰', '小型', '25-28cm', '长毛', '12-14年', 4, '4', 'http://127.0.0.1:9090/web/download/b206f81104ac41bf95ca0b78bf22fcf1.jpeg', '西高地犬是西部高地白梗简称，西部高地白梗原产地英国，产地英国，起源于19世纪。来自苏格兰西部高地的纯白色梗类，在外貌上，脸有点像狐狸，鼻梁比较长。', '<p><span style=\"color: rgb(102, 102, 102);\">据说所有</span><a href=\"https://www.bobocw.com/pet/102.html\" target=\"_blank\" style=\"text-indent: 44px; text-align: left;\">苏格兰梗</a><span style=\"color: rgb(102, 102, 102);\">都是由一个共同祖先继承下来，然后再分布到英国各地。西部高地白梗最初用来捕猎水獭，狐狸和老鼠。19世纪时，在著名饲养者亚盖尔公爵的旦巴顿郡领地上，马尔科姆上校曾在波多罗克村中进行长达60多年的培育工作，与白毛犬品种交配，固定了今日我们所熟知的容貌。所以西部高地白梗曾经叫做波多罗克梗。长有厚实的纯白色皮毛，需要细心照顾。</span></p><h4 style=\"text-align: left;\"><a href=\"https://www.bobocw.com/pet/123.html\" target=\"_blank\">西高地犬</a>发展起源</h4><p style=\"text-indent: 2em; text-align: left;\"><a href=\"https://www.bobocw.com/pet/123.html\" target=\"_blank\">西高地犬</a>和所有的<a href=\"https://www.bobocw.com/pet/102.html\" target=\"_blank\">苏格兰梗</a>可能起源于共同的祖先。<a href=\"https://www.bobocw.com/pet/102.html\" target=\"_blank\">苏格兰梗</a>凯恩梗、<a href=\"https://www.bobocw.com/pet/39.html\" target=\"_blank\">丹迪丁蒙梗</a>和<a href=\"https://www.bobocw.com/pet/123.html\" target=\"_blank\">西高地白梗</a>是来自共同祖先的分支。</p><p style=\"text-indent: 2em; text-align: left;\">权威人士认为，西部高地白梗起源于苏格兰的波塔洛克，在它们第一次展出之前它们在那儿已经有100多年的历史。1916年渡塔洛克的Colonel Malcolm说他的父亲和祖父都喂养此犬。Malcolm犬这种品系可能要追溯到国王詹姆士一世时代，那时詹姆士一世从Argyleshire要了一些土犬。</p><p style=\"text-indent: 2em; text-align: left;\">许多年前，西高地的白梗被称为Roseneath梗，又称作波塔洛克梗， Roseneatt这个名字来源苏格兰敦巴顿耶亚吉尔一个叫杜克的人。</p><p style=\"text-indent: 2em; text-align: left;\">1907年在伦敦的crufts第一次展出了这个品种，1908年第一次在美国养犬俱乐部登记注册。最初登记的名字为Rosenath梗，1909年5月31日正式改名为西部高地白梗。</p><p style=\"text-indent: 2em; text-align: left;\"><a href=\"https://www.bobocw.com/pet/123.html\" target=\"_blank\">西高地犬</a>是一种万能的梗，小小的身体中洋溢着<a href=\"https://www.bobocw.com/pet/102.html\" target=\"_blank\">苏格兰梗</a>的禀性、决心和忠诚。在户外它们是良好的猎犬，敏捷灵巧，非常聪明，在室内又具有所有宠物所应具有的一切，忠实、有理解力和献身精神，而且活泼、热心。</p><p style=\"text-indent: 2em; text-align: left;\"><a href=\"https://www.bobocw.com/pet/123.html\" target=\"_blank\">西高地犬</a>为人们所乐于饲养的原因之是它的耐性。它不需娇惯，喜欢在雪中嬉戏游玩，喜欢跟随滑雪者或行人跨过冰冻的河流和穿过结冰的港湾它们易于梳妆打扮，因为它们仅需很少的修整，并且使它们保持自然状态更好看，也更能显出其性格特征。西部高地自梗被毛僵硬，应该通过正确的修饰和干洗而不是湿洗来保持此种状态。有人认为西部高地白梗很难保持清洁，事实并非如此，每天花不多时间经常用刷子或梳子梳理就可使它保持最佳状态。</p>');
INSERT INTO `type` (`id`, `name`, `origin`, `body`, `height`, `hair`, `lifespan`, `trainability`, `shed`, `img`, `info`, `content`) VALUES (3, '萨摩耶犬', '西伯利亚', '中型', '48-59cm', '长毛', '	12-15年', 3, '4', 'http://127.0.0.1:9090/web/download/02740b49fafd44ffa95d11fb719ece2c.jpeg', '萨摩耶犬(英文：Samoyed)属于工作犬类，以西伯利亚牧民族萨摩人而命名，以其忍耐力与健壮的体格而闻名，所以欧洲探险家曾使用该犬拉雪橇从事南北极探险工作。机警、有力、非常活泼、高贵而文雅。由于它是在寒冷地区的工作犬，所以它拥有非常浓厚的、能抵御各种气候条件的被毛。其萨摩式的微笑，可能正代表此犬的实际性格，即沉稳，优良，性格开朗，对人有亲切感。', '<p style=\"text-indent: 2em; text-align: left;\">19世纪末，毛皮商人为了获取皮毛赢利，将此犬输入美国欧洲等地，并在世界各地广泛培育和繁衍。</p><p style=\"text-indent: 2em; text-align: left;\">许多年来，关于萨摩耶德犬的历史和传说如这种犬一样引人入胜。故事开始于伊朗高原，人类最早的居住地，强大的部落将弱小的部落（连同他们的家庭、牲畜和犬）都赶到很远的地方，以保证自己有充足的食物。被赶走的部落一直向北走，穿过中国（世界文化中心之一），来到白海和叶塞尼河之间的广阔冻土带。他们发现在冰雪的天然屏障后很安全。这些人就是萨摩耶人，塞亚特斯的最早居民。萨摩耶人被认为是纯种蒙古人和芬兰人的过渡民族。在这里，他们一直过着游牧生活，放牧驯鹿。</p><h4 style=\"text-align: left;\"><a href=\"https://www.bobocw.com/pet/111.html\" target=\"_blank\">萨摩耶</a>犬的发展起源</h4><p style=\"text-indent: 2em; text-align: left;\">许多年来，关于萨摩犬的历史和传说如这种犬一样引人人胜。故事开始于伊朗高原，人类最早的居住地，强大的部落将弱小的部落(连同他们的家庭、牲畜和犬)都赶到很远的地方，以保证自己有充足的食物。被赶走的部落一直向北走，穿过中国(世界文化中心之一)，来到白海和叶塞尼河之间的广阔冻土带。他们发现在冰雪的天然屏障后很安全。这些人就是<a href=\"https://www.bobocw.com/pet/111.html\" target=\"_blank\">萨摩耶</a>人，塞亚特斯的最早居民。<a href=\"https://www.bobocw.com/pet/111.html\" target=\"_blank\">萨摩耶</a>人被认为是纯种蒙古人和芬兰人的过渡种族。在这里，他们一直过着游牧生活，放牧驯鹿。<a href=\"https://www.bobocw.com/pet/111.html\" target=\"_blank\">萨摩耶</a>人饲养犬帮助他们放牧驯鹿、拉雪橇，也让犬和他们做伴。</p><p style=\"text-indent: 2em; text-align: left;\">经过几个世纪，萨摩犬一直保持纯种。在所有现代犬种中，萨摩犬是最接近原始的犬种之一，但没有混杂狼或狐的血统。北极的阳光和冰雪给了萨摩犬一身洁白而有冰样光泽的被毛。与人们的长期相处使萨摩犬有着不可思议的理解力。作为驯鹿的保护者而不是杀手使萨摩犬有独一无二的特征。原始居民们那种快乐的孩子气的性格在每只萨摩犬身上都找得到。</p><p style=\"text-indent: 2em; text-align: left;\">和人们长期相处并没有让萨摩犬变得娇生惯养。作为工作犬，萨摩犬在极地远征中保持着一个难以超越的记录。早期极地探险队的雪橇犬(9头公犬，平均体重26.63千克;9头母犬，平均体重22.91千克)在极其严酷的条件下，日复一日地工作。它们虽然要拉相当于自己体重一倍半的物资，但仍然快乐而无忧无虑，这就是萨摩犬的典型性格。每一次的探险，杰克逊一哈斯沃斯(Jackson-Harmsworth)，达克?阿布鲁兹(theDuc d\'Abruzzi)，博奇沃维克(Borchqrevink)，萨克莱顿(Shackleton)，斯考特(Scott)和最著名的沃德.阿莫德森(RoaldAmurdsen)在1911年成功到达南极，这些都为萨摩犬的历史增添光辉的一笔。</p><p style=\"text-indent: 2em; text-align: left;\">在被带入英国不到100年的时间里，萨摩犬在每次犬展中都是大家关注的焦点。亚丽山德拉(Alexandra)皇后非常喜欢这种犬，今天在英国和美国许多饲养者那里还有她的萨摩犬的后代。现在在世界各地都有萨摩犬。出生在西伯利亚的萨摩犬安全地穿越赤道，在南极的冰雪中仍能保持健康。从南极探险队归来的萨摩犬经历了澳大利亚阳光的考验返回英国，并在那里安家。</p>');
INSERT INTO `type` (`id`, `name`, `origin`, `body`, `height`, `hair`, `lifespan`, `trainability`, `shed`, `img`, `info`, `content`) VALUES (4, '哈士奇', '俄罗斯西伯利亚地区', '大型', '51-60cm', '长毛', '13-18年', 4, '4', 'http://127.0.0.1:9090/web/download/167c1fa2ec434c5692fcc472c6a9cfdb.jpeg', '西伯利亚雪撬犬(哈士奇)有许多种类的狗都被称作哈士奇，而通常意义上哈士奇这个词是用来指所有在北方地区的雪橇犬”。哈士奇最初是被北极的土著居民所饲养。据DNA分析，哈士奇是世界上最古老的狗之一', '<p style=\"text-indent: 2em; text-align: left;\">西伯利亚雪撬犬(<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>)有许多种类的狗都被称作<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>，而通常意义上<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>这个词是用来指所有在北方地区的雪橇犬”。<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>最初是被北极的土著居民所饲养。据DNA分析，<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>是世界上最古老的狗之一，但也有一些学者提出质疑，说如果跟狼杂交，就像<a href=\"https://www.bobocw.com/pet/4.html\" target=\"_blank\">阿拉斯加雪橇犬</a>和西伯利亚<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>一样，也可能产生出看起来古老的品种。</p><p style=\"text-indent: 2em; text-align: left;\">在当代有许多品种已经被选择性地繁殖并已经在各种养犬俱乐部注册，包括西伯利亚<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>，格陵兰<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>。库页岛<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>是一种跟日本美拉尼亚丝毛狗，<a href=\"https://www.bobocw.com/pet/96.html\" target=\"_blank\">秋田犬</a>相关的雪橇犬。阿拉斯加<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>生活在在阿拉斯加(除西伯利亚和北极地区)，马更些河<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>是一种不同品种的，生活在北极地区和亚北极区的阿拉斯加与加拿大。</p><h1 style=\"text-align: left;\"><a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>的物种分布</h1><p style=\"text-indent: 2em; text-align: left;\">西伯利亚雪撬犬(<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>)有许多种类的狗都被称作<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>，而通常意义上<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>这个词是用来指所有在北方地区的雪橇犬”。<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>最初是被北极的土著居民所饲养。</p><p style=\"text-indent: 2em; text-align: left;\">在当代有许多品种已经被选择性地繁殖并已经在各种养犬俱乐部注册，包括西伯利亚<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>，格陵兰<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>。库页岛<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>是一种跟日本美拉尼亚丝毛狗，<a href=\"https://www.bobocw.com/pet/96.html\" target=\"_blank\">秋田犬</a>相关的雪橇犬。阿拉斯加<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>生活在在阿拉斯加(除西伯利亚和北极地区)，马更些河<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>是一种不同品种的，生活在北极地区和亚北极区的阿拉斯加与加拿大。</p><h2 style=\"text-align: left;\"><a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>的发展起源</h2><p style=\"text-indent: 2em; text-align: left;\">西伯利亚雪橇犬是东西伯利亚游牧民伊奴特乔克治族饲养的犬种，<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>最初是被用来拉雪橇，参与大型捕猎活动，保护村庄，和引导驯鹿及守卫等工作。而且，在西伯利亚恶劣的环境下工作。西伯利亚雪橇犬几个世纪以来，一直单独地生长在西伯利亚地区。20世纪初，被毛皮商人带至美国。一转眼，此犬便成为举世闻名的拉雪橇竞赛之冠军犬。现今，该犬则作为优良的伴侣犬备受人们喜爱。西伯利亚雪橇犬历史记载中，西伯利亚雪橇犬的祖先，最早要追溯到新石器时代之前。当时一群中亚的猎人们移居到极地(也就是西伯利亚)的尽头生活，经过了很长时间，这群跟随在猎人身边的狗儿，在长期与北极狼群交配繁育之下，发展成为北方特有的犬种。</p><p style=\"text-indent: 2em; text-align: left;\">在这群穿越过北极圈，最后选择在格陵兰落脚的人们中间，有一个部落，就是后来发展西伯利亚雪橇犬的楚科奇人。早期，楚科奇人将这群跟随在他们身边的狗儿训练为可以用来拉雪橇并且看守家畜的工作犬，因为它们耐寒、食量小、工作起来又相当认真。因此当时还被认为是部落中相当重要的财富。而这群早期被称之为西伯利亚楚科奇犬的狗儿，也就是后来<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>的祖先。据说<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>这个名称，是爱斯基摩人的俚语--沙哑的叫声的讹传，因为当时的狗儿们叫声较为低沉沙哑因此有了这个奇妙的称号。</p><p style=\"text-indent: 2em; text-align: left;\"><a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>起源于18世纪初，阿拉斯加的美国人开始知道<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>雪橇犬。1909年，西伯利亚<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>雪橇犬第一次在阿拉斯加的犬赛中亮相。1930年，西伯利亚<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>雪橇犬俱乐部得到了美国养犬俱乐部的正式承认。传说中，西伯利亚雪橇犬是<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>的祖先，经过了长久时间，其中包括<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>、<a href=\"https://www.bobocw.com/pet/111.html\" target=\"_blank\">萨摩耶</a>、<a href=\"https://www.bobocw.com/pet/4.html\" target=\"_blank\">阿拉斯加雪橇犬</a>等。西伯利亚<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>是原始的古老犬种，名字的由来是源自<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>独特的嘶哑叫声。在西伯利亚东北部的原始部落楚克奇族人，用这种外型酷似狼的<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>犬作为最原始的交通工具来拉雪橇，并用<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>犬猎取和饲养驯鹿，或者繁殖后带出他们居住的冻土地带来换取温饱。由于<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>体型小巧结实，胃口小，无体臭且耐寒非常适应极地的气候环境，而成为楚克奇人的重要财产。</p><p style=\"text-indent: 2em; text-align: left;\"><a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>(西伯利亚雪橇犬)是东西伯利亚游牧民族伊奴特乔克治族饲养的犬种，一向担任拉雪橇，引导驯鹿及守卫等工作。而且，<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>能在西伯利亚恶劣的环境下工作。<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>(西伯利亚雪橇犬)几个世纪以来，一直单独的生长在西伯利亚地区。20世纪初，被毛皮商人带至美国。一转眼，<a href=\"https://www.bobocw.com/pet/59.html\" target=\"_blank\">哈士奇</a>犬便成为举世闻名的拉雪橇竞赛之冠军犬。</p>');
INSERT INTO `type` (`id`, `name`, `origin`, `body`, `height`, `hair`, `lifespan`, `trainability`, `shed`, `img`, `info`, `content`) VALUES (5, '柯基犬', '瑞典', '小型', '31-35cm', '长毛', '12-14年', 4, '3', 'http://127.0.0.1:9090/web/download/1866ecfbb29d49689d782904d50614cb.jpg', '威尔士柯基犬又称之为威尔士短腿狗，是时下很受欢迎的一个犬种，由于身长腿短长相很萌尤其受到了女生们的喜爱。', '<p style=\"text-indent: 2em; text-align: left;\">威尔士<a href=\"https://www.bobocw.com/pet/2.html\" target=\"_blank\">柯基</a>至少公元920年彭布罗克威尔士<a href=\"https://www.bobocw.com/pet/2.html\" target=\"_blank\">柯基</a>犬已存在于英国了。</p><p style=\"text-indent: 2em; text-align: left;\">它是由卡狄根犬与彭布罗克犬两种变种而来。彭布罗克犬比卡狄根犬名气大。由法兰德斯工人携带过来的犬种，根据其近似狐狸的头部，有人认为，本犬与尖嘴犬祖先关系密切。但也有人认为，是随着威尔士与瑞典贸易传至威尔士的瑞典短脚长身犬和土著犬交配，产生了<a href=\"https://www.bobocw.com/pet/2.html\" target=\"_blank\">柯基</a>犬。卡狄根犬和彭布罗克犬一样是擅长牧牛的犬种。由于身轻如燕，动作机敏，后脚跟被咬的家畜发怒时，此犬能以极快的速度逃开。1934年，英国正式公认为卡狄根犬与彭布罗克犬两种不同品种。</p><p style=\"text-indent: 2em; text-align: left;\">在育种专家不断的培育以及训练下已经将其与生俱来与其它犬相斗的野性慢慢去除了，如今市场上<a href=\"https://www.bobocw.com/pet/2.html\" target=\"_blank\">柯基</a>的价格也不便宜。</p><p style=\"text-indent: 2em; text-align: left;\"><a href=\"https://www.bobocw.com/pet/2.html\" target=\"_blank\">柯基</a>犬即威尔士<a href=\"https://www.bobocw.com/pet/2.html\" target=\"_blank\">柯基</a>犬（著名犬种）。威尔士<a href=\"https://www.bobocw.com/pet/2.html\" target=\"_blank\">柯基</a>犬共分两种：<a href=\"https://www.bobocw.com/pet/191.html\" target=\"_blank\">卡迪根威尔士</a><a href=\"https://www.bobocw.com/pet/2.html\" target=\"_blank\">柯基</a>犬和彭布罗克威尔士<a href=\"https://www.bobocw.com/pet/2.html\" target=\"_blank\">柯基</a>犬。两者比较，彭布罗克<a href=\"https://www.bobocw.com/pet/2.html\" target=\"_blank\">柯基</a>犬的体形较短，腿骨更直、更轻，而威尔士<a href=\"https://www.bobocw.com/pet/2.html\" target=\"_blank\">柯基</a>犬背毛的质地更好；但在性情上，彭布罗克<a href=\"https://www.bobocw.com/pet/2.html\" target=\"_blank\">柯基</a>犬显得不安分，容易激动，没有<a href=\"https://www.bobocw.com/pet/191.html\" target=\"_blank\">卡迪根威尔士</a><a href=\"https://www.bobocw.com/pet/2.html\" target=\"_blank\">柯基</a>犬那么驯服。从12世纪的理查一世到现在的女王伊丽莎白二世，<a href=\"https://www.bobocw.com/pet/2.html\" target=\"_blank\">柯基</a>犬一直是英国王室的宠物。</p>');
INSERT INTO `type` (`id`, `name`, `origin`, `body`, `height`, `hair`, `lifespan`, `trainability`, `shed`, `img`, `info`, `content`) VALUES (6, '法国斗牛犬', '法国', '小型', '30-31cm', '短毛', '11-12年', 1, '1', 'http://127.0.0.1:9090/web/download/ae54f6d8d34f47389e118cfc9702e32b.jpeg', '法国斗牛犬(FRENCH BULLDOG)是一种活泼、聪明、肌肉发达的狗，骨骼沉重，被毛平滑、结构紧凑，体型中等或较小。表情显得警惕、好奇而感兴趣。除了切除狼爪以外，对他的任何改动都是错误的，属于失格。 法国斗牛犬亲切，敦厚，忠诚，执著，勇敢，具有独特的品位，而且完全表露于表情与动作。对小孩和善，同时也是作风彪悍，能力强，对于新鲜事物有极强的好奇心的优秀玩具犬。', '<p style=\"text-indent: 2em; text-align: left;\"><a href=\"https://www.bobocw.com/pet/37.html\" target=\"_blank\">法国斗牛</a>犬，英文：French Bulldog，原产地法国。 祖先是英国斗牛犬，特别是竖耳玩具斗牛犬。大约在1860年，许多玩具斗牛犬从英国流入法国，同当地其他品种犬杂交而最终变成这种体型小，头盖平、玫瑰耳或蝙蝠耳的<a href=\"https://www.bobocw.com/pet/37.html\" target=\"_blank\">法国斗牛</a>犬。</p><p style=\"text-indent: 2em; text-align: left;\">关于其起源，有很多种说法，其中最有力的一种认为：1860年之际，英国有很多作为玩赏犬的斗牛犬被送到法国，和八哥犬，梗犬交配，生下此种犬。当时这种狗深受贵妇喜爱。1990年，出生蝙蝠耳与玫瑰耳两型，以蝙蝠耳为标准型。</p><p style=\"text-indent: 2em; text-align: left;\">1868年巴黎就出现了一种小型斗牛犬，这就是最早的<a href=\"https://www.bobocw.com/pet/37.html\" target=\"_blank\">法国斗牛</a>犬。1871年正值巴黎城堡处于普鲁士人包围之中时，该犬在法国已经很为流行。1889年<a href=\"https://www.bobocw.com/pet/37.html\" target=\"_blank\">法国斗牛</a>犬首次展出，很快引起人们的重视和钟爱。爱德华七世就非常钟爱该犬种。</p>');
INSERT INTO `type` (`id`, `name`, `origin`, `body`, `height`, `hair`, `lifespan`, `trainability`, `shed`, `img`, `info`, `content`) VALUES (7, '美国短毛猫', '美国', '中型', '约50cm', '短毛', '10-15年', 4, '3', 'http://127.0.0.1:9090/web/download/1bf9f8207e20445eac5dba7cb9b425da.jpeg', '美国短毛猫素以体格魁伟，骨骼粗壮，肌肉发达，生性聪明，性格温顺著称，是短毛猫类中大型品种。皮毛厚密，毛色多达30种，其中以银色条纹品种最为名贵。', '<p style=\"text-indent: 2em;\"><span style=\"color: rgb(102, 102, 102);\">美国最早的家猫据说是随17世纪的移民来到新大陆的猫咪，接下来的几个世纪里，壮实而具有工作效率的猫咪扩散到整个美国，它们大多是熟练的捕鼠能手而非家庭宠物。但到了20世纪初，一种庭院捕鼠猫的改良品种开始出现，被称为短毛家猫。人们精心的繁育进一步改良了家猫品种，到20世纪60年代，该品种被更名为美国短毛猫，逐渐在纯种猫咪展览上吸引人们的注意力。美国短毛猫健康而且性格坚忍，是适合几乎任何类型家庭的完美宠物。</span></p><p style=\"text-indent: 2em;\">关于美国短毛猫的起源有两种说法：一部分人认为该猫是美洲大陆土著猫，经长期选育而成；一部分人认为它是17世纪从欧洲随美国移民带来后，经改良而育成。</p><p style=\"text-indent: 2em;\">还记得五月花号客轮和感恩节吧，18世纪末英国的105名清教徒来到美国大陆，同时也带去了一些欧洲猫。他们将带来的短毛猫和美国当地猫进行杂交，经过精心的培育改良，从而得到了体质强壮、体型优美的美国短毛猫。这种猫受到当地美国人的喜爱，并在猫展上得到了很高的荣誉。</p><p><br></p><p><br></p>');
INSERT INTO `type` (`id`, `name`, `origin`, `body`, `height`, `hair`, `lifespan`, `trainability`, `shed`, `img`, `info`, `content`) VALUES (8, '斯芬克斯猫', '加拿大', '中型', '约50cm', '无毛', '12年', 5, '1', 'http://127.0.0.1:9090/web/download/dd0f97860b3140d1b6bd894f5a8cfd9b.jpg', '加拿大无毛猫（Canadian Hairless）亦称斯芬克斯猫，是加拿大安大略省多伦多市养猫爱好者在1966年从一窝几乎是无毛的猫仔中，经过近交选育，特意为对猫毛过敏的爱猫者培育成的。这种猫是自然的基因突变产生的宠物猫，除了在耳、口、鼻、尾前段、脚等部位有些又薄又软的胎毛外，其它全身部分均无毛，皮肤多皱有弹性。加拿大无毛猫性情温顺，独立性强，无攻击性，能与其它猫狗相处。', '<p>斯芬克斯猫又名斯芬克斯无毛猫。早在1700年前就有南美墨西哥土著居民饲养过这种无毛猫的记载。但直到该品种在猫展中获得成功人们才开始注意它，并对它产生兴趣。TlCA承认该品种，此种猫在2005年被认定为稀有品种。</p><p>有记载的最早无毛猫是一对名叫内利和迪克的同窝出生的兄弟。1903年，美国新墨西哥州人辛尼克从普韦布洛的美国本土印第安人手中买下了它们。1966年，无毛猫再次发现于加拿大多伦多，<a href=\"https://www.bobocw.com/pet/211.html\" target=\"_blank\">加拿大无毛猫</a>的名字由此而来。此后不久，在美国的明尼苏达也发现了无毛猫。随着无毛猫的名声越来越大，世界各地也都有发现无毛猫的报道。于是，一些爱猫人士培育出斯芬克斯猫，这种斯芬克斯猫不容易受到基因疾病的侵扰，也不是近亲繁殖所生育的残疾。</p><p><br></p>');
INSERT INTO `type` (`id`, `name`, `origin`, `body`, `height`, `hair`, `lifespan`, `trainability`, `shed`, `img`, `info`, `content`) VALUES (9, '布偶猫', '美国', '中型', '约50厘米', '长毛', '10-15年', 3, '3', 'http://127.0.0.1:9090/web/download/d30307458bda410eaa34922583ac8209.jpeg', '布偶猫又称布拉多尔猫，是猫中体形和体重较大的一种。布偶猫于1960年开始繁育，1965年在美国获得认可。布偶猫头呈V形，眼大而圆，被毛丰厚，四肢粗大，身体柔软，多为三色或双色猫。布偶猫全身非常松弛，像软绵绵的布偶一样。它性格温顺、恬静，对人非常友善，对疼痛的忍受性相当强，常被误认为缺乏疼痛感。它非常能容忍孩子的玩耍，也因此被称为布偶猫，是非常理想的家养宠物。', '<p style=\"text-indent: 2em; text-align: left;\"><a href=\"https://www.bobocw.com/pet/202.html\" target=\"_blank\">布偶猫</a>是一个非常聪明的品种，它性情温顺、安详，爱交际，和其他猫或狗相处友好，叫声轻柔，感情丰富，有爱心，喜欢有人陪伴，对人非常友善，全身特别松弛、柔软，忍耐性强，非常能容忍人们的玩弄。</p><p style=\"text-indent: 2em; text-align: left;\"><a href=\"https://www.bobocw.com/pet/202.html\" target=\"_blank\">布偶猫</a>喜欢讨好主人，总是形影不离地围着主人转。这种猫非常好静，但也爱玩玩具，并喜欢参与家中的日常生活。<a href=\"https://www.bobocw.com/pet/202.html\" target=\"_blank\">布偶猫</a>异常温柔，缺乏保护自己的本能，因此必须作为宠物养在深闺，而不许出门。</p><p style=\"text-indent: 2em;\">尽管<a href=\"https://www.bobocw.com/pet/202.html\" target=\"_blank\">布偶猫</a>是一个新品种，它们的历史渊源却始终很不明朗。20世纪60年代，加利福尼亚的培育者Ann Baker培育出了最早的<a href=\"https://www.bobocw.com/pet/202.html\" target=\"_blank\">布偶猫</a>，它们的父亲是只名叫Warbucks的雄性<a href=\"https://www.bobocw.com/pet/201.html\" target=\"_blank\">伯曼猫</a>，而母亲则是叫做Josephine的白色非纯种长毛猫。她说<a href=\"https://www.bobocw.com/pet/202.html\" target=\"_blank\">布偶猫</a>被抱起来的时候就会全身“绵软”。随后Ann Baker成立了一个品种协会，但那时的<a href=\"https://www.bobocw.com/pet/202.html\" target=\"_blank\">布偶猫</a>还没有得到其他协会的承认。此后，又有许多人培养出了<a href=\"https://www.bobocw.com/pet/202.html\" target=\"_blank\">布偶猫</a>，这才创造了如今被各大主流协会承认的<a href=\"https://www.bobocw.com/pet/202.html\" target=\"_blank\">布偶猫</a>品种。<a href=\"https://www.bobocw.com/pet/202.html\" target=\"_blank\">布偶猫</a>的成功，应该归功于人们对安静的室内猫的需要。如今，一些相似的品种正陆续被培养出来，并且都有一个温馨的名字。</p><p><br></p>');
INSERT INTO `type` (`id`, `name`, `origin`, `body`, `height`, `hair`, `lifespan`, `trainability`, `shed`, `img`, `info`, `content`) VALUES (10, '中华田园猫', '中国', '中型', '约50cm', '短毛', '10-15年', 4, '3', 'http://127.0.0.1:9090/web/download/f8438cbf40b14597a27a34338159be5f.webp', '中华田园猫中狸花猫原产于中国。 中华田园猫性格活泼，独立，好奇心重，捕鼠能力强。 中华田园猫经常自己清理毛发，并且常掩盖粪便，防止天敌从其粪便气味发现和追踪。中华田园猫为肉食性动物，有昼伏夜出的习性。中华田园猫在早晨和晚上进食；配种时间一般在夜间。', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\">过去中国的普通家猫一直没有学名，近些年来不少网友将中国普通家猫命名为“中华田园猫”。经过CFA中国长城猫俱乐部历时六年的不懈努力，“中华田园猫”类中的“中国狸花猫”成为了中国目前唯一被世界认可的中国本土自然品种。</span></p><p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\">土猫（学名：Domestic Shorthair）是猫科猫属的哺乳动物，又称中华田园猫，是各国本土家猫的统称，涵盖狸花猫、狮子猫、简州猫等品种</span><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\"><sup><em> </em></sup></span><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\">。其毛色多样，包括虎斑、乳白、纯黑等多种类型，体型因遗传差异较大，普遍具有圆头、圆脚掌及中等长度尾巴的形态特征，体重通常为6-16磅</span><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\"><sup><em> </em></sup></span><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\">。作为全世界最受欢迎的猫种，其全球总数超过6亿只，仅美国境内就有约8000万只。</span></p>');
INSERT INTO `type` (`id`, `name`, `origin`, `body`, `height`, `hair`, `lifespan`, `trainability`, `shed`, `img`, `info`, `content`) VALUES (11, '中华田园犬', '中国', '中型', '25～55厘米左右', '短毛', '15年', 4, '2', 'http://127.0.0.1:9090/web/download/f7c30656d29b455ea6657a5e189c9305.webp', '中华田园犬是中国汉族几千年农耕社会背景下的产物，是历史和文化的活化石。随着城市化发展迅速，中华田园犬现在常被当作宠物犬，也广泛用于农村的看家护院和早期的狩猎。作为人类最早驯养的动物之一，中华田园犬至今仍被称作“人类最忠实的朋友”。', '<p><span style=\"color: rgb(51, 51, 51); background-color: rgb(255, 255, 255); font-size: 14px;\">中华田园犬（学名：Canis lupus familiaris），是食肉目犬科犬属动物，又名土狗、柴狗。成犬肩高约25-55厘米，体重约10-30公斤，其头部特征接近于灰狼的外貌，嘴尖、短；额平；耳位高，耳小且直立或半直立；站立静止时，后腿平直并垂直于地面；体型中等大小；棕毛为主，毛质粗，颜色黄、白、黑、杂色；尾巴向上翘起。中华田园犬是为了区别日本秋田犬而作出的命名。</span></p>');
COMMIT;

SET FOREIGN_KEY_CHECKS = 1;
